60: bool wxDynamicLibrary::Load(const wxString& libnameOrig, int flags)
61: {
62:     wxASSERT_MSG(m_handle == nullptr, wxT("Library already loaded."));
63: 
64:     // add the proper extension for the DLL ourselves unless told not to
65:     wxString libname = libnameOrig;
66:     if ( !(flags & wxDL_VERBATIM) )
67:     {
68:         // and also check that the libname doesn't already have it
69:         wxString ext;
70:         wxFileName::SplitPath(libname, nullptr, nullptr, &ext);
71:         if ( ext.empty() )
72:         {
73:             libname += GetDllExt(wxDL_MODULE);
74:         }
75:     }
76: 
77:     m_handle = RawLoad(libname, flags);
78: 
79:     if ( m_handle == nullptr && !(flags & wxDL_QUIET) )
80:     {
81:         ReportError(_("Failed to load shared library '%s'"), libname);
82:     }
83: 
84:     return IsLoaded();
85: }
