87: void *wxDynamicLibrary::DoGetSymbol(const wxString &name, bool *success) const
88: {
89:     wxCHECK_MSG( IsLoaded(), nullptr,
90:                  wxT("Can't load symbol from unloaded library") );
91: 
92:     void *symbol = RawGetSymbol(m_handle, name);
93: 
94:     if ( success )
95:         *success = symbol != nullptr;
96: 
97:     return symbol;
98: }
