100: void *wxDynamicLibrary::GetSymbol(const wxString& name, bool *success) const
101: {
102:     void *symbol = DoGetSymbol(name, success);
103:     if ( !symbol )
104:     {
105:         ReportError(_("Couldn't find symbol '%s' in a dynamic library"), name);
106:     }
