139:     {
140:         const wxString path = wxString::FromUTF8(info->dlpi_name);
141: 
142:         wxDynamicLibraryDetails details;
143:         details.m_path = path;
144:         details.m_name = path.AfterLast(wxT('/'));
145: 
146:         // Find the first and last address belonging to this module.
147:         decltype(info->dlpi_addr) start = 0, end = 0;
148:         for ( decltype(info->dlpi_phnum) n = 0; n < info->dlpi_phnum; n++ )
149:         {
150:             const auto& segment = info->dlpi_phdr[n];
151:             if ( !segment.p_vaddr || !segment.p_memsz )
152:                 continue;
153: 
154:             if ( !start || segment.p_vaddr < start )
155:                 start = segment.p_vaddr;
156: 
157:             if ( !end || segment.p_vaddr + segment.p_memsz > end )
158:                 end = segment.p_vaddr + segment.p_memsz;
159:         }
160: 
161:         details.m_address = wxUIntToPtr(info->dlpi_addr + start);
162:         details.m_length = end - start;
163: 
164:         // try to extract the library version from its name
165:         const size_t posExt = path.rfind(wxT(".so"));
166:         if ( posExt != wxString::npos )
167:         {
168:             if ( path.c_str()[posExt + 3] == wxT('.') )
169:             {
170:                 // assume "libfoo.so.x.y.z" case
171:                 details.m_version.assign(path, posExt + 4, wxString::npos);
172:             }
173:             else
174:             {
175:                 size_t posDash = path.find_last_of(wxT('-'), posExt);
176:                 if ( posDash != wxString::npos )
177:                 {
178:                     // assume "libbar-x.y.z.so" case
179:                     posDash++;
180:                     details.m_version.assign(path, posDash, posExt - posDash);
181:                 }
182:             }
183:         }
184: 
185:         auto dlls = static_cast<wxDynamicLibraryDetailsArray*>(data);
186:         dlls->push_back(std::move(details));
187: 
188:         // Return 0 to keep iterating.
189:         return 0;
190:     }
191: };
